package com.tecsup.minishop.service;
import com.tecsup.minishop.model.Product; import com.tecsup.minishop.repository.ProductRepository; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.test.context.ActiveProfiles; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
@SpringBootTest @ActiveProfiles("test") class ProductServiceIntegrationTest { @Autowired ProductService productService; @MockBean ProductRepository productRepository; @Test void shouldSaveValidProduct(){Product input=Product.builder().name("Auriculares Sony").price(320.0).stock(15).build(), expected=Product.builder().id(1L).name("Auriculares Sony").price(320.0).stock(15).build(); when(productRepository.save(any(Product.class))).thenReturn(expected); assertThat(productService.save(input).getId()).isEqualTo(1L); verify(productRepository).save(any(Product.class));} @Test void shouldThrowExceptionWhenPriceIsInvalid(){Product p=Product.builder().name("Invalido").price(0.0).stock(5).build(); assertThatThrownBy(()->productService.save(p)).isInstanceOf(IllegalArgumentException.class).hasMessage("El precio debe ser mayor a cero"); verify(productRepository,never()).save(any());} @Test void shouldThrowExceptionWhenStockIsNegative(){Product p=Product.builder().name("Sin stock").price(100.0).stock(-1).build(); assertThatThrownBy(()->productService.save(p)).isInstanceOf(IllegalArgumentException.class).hasMessage("El stock no puede ser negativo");} @Test void shouldReturnAllProducts(){when(productRepository.findAll()).thenReturn(List.of(Product.builder().id(1L).name("A").price(10.0).stock(2).build(),Product.builder().id(2L).name("B").price(20.0).stock(3).build())); assertThat(productService.findAll()).hasSize(2); verify(productRepository).findAll();} @Test void shouldThrowExceptionWhenProductNotFound(){when(productRepository.findById(99L)).thenReturn(Optional.empty()); assertThatThrownBy(()->productService.findById(99L)).isInstanceOf(RuntimeException.class).hasMessageContaining("Producto no encontrado con id: 99");}}
